mapper.select:
select 
from CHB_EQU_HOLD_CHECK
where 1=1

	and INDENTIFY_MARK=#{indentifyMark,jdbcType=VARCHAR}


	and ORG_INDENTIFY_MARK=#{orgIndentifyMark,jdbcType=VARCHAR}


	and REGIST_BANK_CODE=#{registBankCode,jdbcType=VARCHAR}


	and IS_BELONG_BANK=#{isBelongBank,jdbcType=CHAR}


	and THE_BANK_NAME=#{theBankName,jdbcType=VARCHAR}


	and THE_BANK_CODE=#{theBankCode,jdbcType=VARCHAR}


	and HOLDER_MARK=#{holderMark,jdbcType=CHAR}


	and HOLDER_REGION=#{holderRegion,jdbcType=VARCHAR}


	and HOLDER_TYPE=#{holderType,jdbcType=CHAR}


	and PERSONAL_IDENTIFY_TYPE=#{personalIdentifyType,jdbcType=CHAR}


	and INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	and OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}


	and IDENTIFY_NUMBER=#{identifyNumber,jdbcType=VARCHAR}


	and SPV_CAP_ACC_BANK=#{spvCapAccBank,jdbcType=VARCHAR}


	and OTHER_CAP_ACC_BANK=#{otherCapAccBank,jdbcType=VARCHAR}


	and SPV_REGIST_CODE=#{spvRegistCode,jdbcType=VARCHAR}


	and HOLDER_DATE=#{holderDate,jdbcType=TIMESTAMP}


	and HOLDER_NAME=#{holderName,jdbcType=VARCHAR}


	and HOLDER_SEX=#{holderSex,jdbcType=CHAR}


	and HOLDER_RISK_PREFER=#{holderRiskPrefer,jdbcType=VARCHAR}


	and HOLDER_CELLPHONE=#{holderCellphone,jdbcType=VARCHAR}


	and HOLDER_TELEPHONE=#{holderTelephone,jdbcType=VARCHAR}


	and IS_SUBMIT=#{isSubmit,jdbcType=CHAR}


	and HOLDER_EMAIL=#{holderEmail,jdbcType=VARCHAR}


	and STATUS=#{status,jdbcType=VARCHAR}


	and AGENT=#{agent,jdbcType=VARCHAR}


	and INTERF_CHECK_RESULT=#{interfCheckResult,jdbcType=VARCHAR}

select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK,sub.INDENTIFY_MARK isOrNoSubmit,a.FUND_ACC_PLACE,a.HOLDER_CLASSIFY from CHB_EQU_HOLD_CHECK a left join chb_equ_sub sub on sub.INDENTIFY_MARK=a.MERGER_INDENTIFY_MARK and sub.SUBMIT_STATUS in ('02','03') left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,ifnull(PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE),ifnull(OTHER_IDENTIFY_NAME,1),IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND ifnull(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=ifnull(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and ifnull(a.OTHER_IDENTIFY_NAME,1)=ifnull(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
and a.MERGER_INDENTIFY_MARK like concat_ws('','%', #{mergerIndentifyMark,jdbcType=VARCHAR},'%')
and a.IDENTIFY_NUMBER like concat_ws('','%', #{identifyNumber,jdbcType=VARCHAR},'%')
and a.HOLDER_NAME like concat_ws('','%', #{holderName,jdbcType=VARCHAR},'%')
#{items,jdbcType=VARCHAR}
and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d') >= #{dataTimeStart,jdbcType=VARCHAR}
and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d') <= #{dataTimeEnd,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
order by (CASE WHEN a.INSTITUTION_IDENTIFY_TYPE IS NULL then 'A' else 'B' end) desc,IMARK desc,a.INDENTIFY_MARK desc

select 
from CHB_EQU_HOLD_CHECK
where
HOLDER_NAME=#{holderName,jdbcType=VARCHAR}

	and PERSONAL_IDENTIFY_TYPE=#{personalIdentifyType,jdbcType=CHAR}


	and INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	and OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}

and IDENTIFY_NUMBER=#{identifyNumber,jdbcType=VARCHAR}

select from CHB_EQU_HOLD_CHECK where 1=1 AND OPERATE_STATUS = '01'
AND concat_ws('',REGIST_BANK_CODE, '_', IDENTIFY_NUMBER, '_',HOLDER_NAME, '_', PERSONAL_IDENTIFY_TYPE, '_', INSTITUTION_IDENTIFY_TYPE, '_', OTHER_IDENTIFY_NAME) IN
#{key,jdbcType=VARCHAR}

select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK,a.FUND_ACC_PLACE,a.HOLDER_CLASSIFY from CHB_EQU_HOLD_CHECK a left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND ifnull(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=ifnull(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and ifnull(a.OTHER_IDENTIFY_NAME,1)=ifnull(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
#{items.indentifyMark,jdbcType=VARCHAR}
order by (CASE WHEN a.INSTITUTION_IDENTIFY_TYPE IS NULL then 'A' else 'B' end) desc,IMARK desc,a.INDENTIFY_MARK desc

mapper.update:
     UPDATE CHB_EQU_HOLD_CHECK HOLD
       SET MERGER_INDENTIFY_MARK =  #{indentifyMark,jdbcType=VARCHAR}
       ,OPERATE_STATUS = '02'
       ,UPDATE_TIME = NOW()
	  WHERE concat_ws('',HOLD.REGIST_BANK_CODE, '_', HOLD.IDENTIFY_NUMBER, '_',HOLD.HOLDER_NAME, '_', HOLD.PERSONAL_IDENTIFY_TYPE, '_', HOLD.INSTITUTION_IDENTIFY_TYPE, '_', HOLD.OTHER_IDENTIFY_NAME) = #{key,jdbcType=VARCHAR}

update CHB_EQU_HOLD_CHECK
set MERGER_INDENTIFY_MARK =
#{mergerindentifymark,jdbcType=VARCHAR},
OPERATE_STATUS =
#{operatestatus,jdbcType=VARCHAR},
UPDATE_TIME = NOW()

	,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}

where HOLDER_NAME=#{holderName,jdbcType=VARCHAR}

	and PERSONAL_IDENTIFY_TYPE=#{personalIdentifyType,jdbcType=CHAR}


	and
	INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	and OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}

and IDENTIFY_NUMBER=#{identifyNumber,jdbcType=VARCHAR}

mapper.delete:
delete from CHB_EQU_HOLD hold
where
hold.IDENTIFY_NUMBER = #{identifyNumber,jdbcType=VARCHAR}
AND hold.HOLDER_NAME = #{holderName,jdbcType=VARCHAR}

	AND hold.PERSONAL_IDENTIFY_TYPE = #{personalIdentifyType,jdbcType=VARCHAR}


	AND hold.INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	AND hold.OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}

delete from CHB_EQU_SUB hold
where
hold.IDENTIFY_NUMBER = #{identifyNumber,jdbcType=VARCHAR}
AND hold.HOLDER_NAME = #{holderName,jdbcType=VARCHAR}

	AND hold.PERSONAL_IDENTIFY_TYPE = #{personalIdentifyType,jdbcType=VARCHAR}


	AND hold.INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	AND hold.OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}

delete from CHB_EQU_HOLD_CHECK hold
where
hold.INDENTIFY_MARK = #{indentifyMark,jdbcType=VARCHAR}
AND hold.REGIST_BANK_CODE = #{registBankCode,jdbcType=VARCHAR}

mapper.update:
UPDATE CHB_EQU_HOLD_CHECK as A, ( select REGIST_BANK_CODE, IDENTIFY_NUMBER, HOLDER_NAME, PERSONAL_IDENTIFY_TYPE, INSTITUTION_IDENTIFY_TYPE, OTHER_IDENTIFY_NAME, INDENTIFY_MARK from ( select TEMP.* from (
select #{item.registBankCode,jdbcType=VARCHAR} REGIST_BANK_CODE, #{item.identifyNumber,jdbcType=VARCHAR} IDENTIFY_NUMBER, #{item.holderName,jdbcType=VARCHAR} HOLDER_NAME, IFNULL(#{item.personalIdentifyType,jdbcType=VARCHAR},'null') PERSONAL_IDENTIFY_TYPE, IFNULL(#{item.institutionIdentifyType,jdbcType=VARCHAR},'null') INSTITUTION_IDENTIFY_TYPE, IFNULL(#{item.otherIdentifyName,jdbcType=VARCHAR},'null') OTHER_IDENTIFY_NAME, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK from dual
) TEMP ) de ) AS B set A.MERGER_INDENTIFY_MARK = B.INDENTIFY_MARK, A.OPERATE_STATUS = '02' where A.REGIST_BANK_CODE = B.REGIST_BANK_CODE AND A.IDENTIFY_NUMBER = B.IDENTIFY_NUMBER AND A.HOLDER_NAME= B.HOLDER_NAME AND ifnull(A.PERSONAL_IDENTIFY_TYPE,'null') = B.PERSONAL_IDENTIFY_TYPE AND ifnull(A.INSTITUTION_IDENTIFY_TYPE,'null') = B.INSTITUTION_IDENTIFY_TYPE AND ifnull(A.OTHER_IDENTIFY_NAME,'null') = B.OTHER_IDENTIFY_NAME;
